"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["82209"],{78305(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.no_exigencia.grupo_com_finalidades_diferentes","status":422,"titulo":"Todos os documentos de um grupo pertencem ao mesmo formul\xe1rio"},"descricao":{"codigo":"uniplus.selecao.no_exigencia.grupo_com_finalidades_diferentes","requisitos":[],"oQueAconteceu":["Cada documento exigido pertence a um formul\xe1rio do candidato (a finalidade): inscri\xe7\xe3o,\\nisen\xe7\xe3o de taxa ou habilita\xe7\xe3o. Os documentos de um mesmo grupo (E ou OU) precisam pertencer\\ntodos ao mesmo formul\xe1rio. O grupo apontado mistura documentos de formul\xe1rios diferentes, ou\\ndocumentos com formul\xe1rio e documentos sem formul\xe1rio. A inscri\xe7\xe3o e a isen\xe7\xe3o podem dividir a\\nmesma fase, e por isso a regra olha o formul\xe1rio, e n\xe3o s\xf3 a fase.","A confer\xeancia acontece na cria\xe7\xe3o do grupo, depois de\\n[`grupo_com_fases_diferentes`](/erros/uniplus.selecao.no_exigencia.grupo_com_fases_diferentes)\\ne antes de\\n[`repeticao_de_entidade_aninhada`](/erros/uniplus.selecao.no_exigencia.repeticao_de_entidade_aninhada).\\nA primeira viola\xe7\xe3o encontrada interrompe o processamento."],"comoResolver":["Na defini\xe7\xe3o, separe os documentos em grupos distintos, um por formul\xe1rio, ou ajuste o\\nformul\xe1rio de cada documento para que o grupo tenha s\xf3 um."],"ondeAparece":["Defini\xe7\xe3o de documentos exigidos do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"No exigencia"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);